sol=[]
for w in range(5):
    for p in range(35):
        x=p//7; y=p%7
        sol.append((y - w*x)%7)
print(len(sol))
print(sol)
# verify
ok=True
for w in range(5):
    counts=[0]*7
    groups=[[] for _ in range(7)]
    for p in range(35):
        g=sol[w*35+p]
        counts[g]+=1; groups[g].append(p)
    if counts != [5]*7:
        print('bad counts',w,counts); ok=False
seen={}
repeats=[]
for w in range(5):
    for g in range(7):
        ps=[p for p in range(35) if sol[w*35+p]==g]
        for i in range(len(ps)):
            for j in range(i+1,len(ps)):
                pair=(ps[i],ps[j])
                if pair in seen:
                    repeats.append((pair,seen[pair],(w,g)))
                else:
                    seen[pair]=(w,g)
print('ok', ok, 'repeats', len(repeats), 'pairs', len(seen))
# print weeks in rows
for w in range(5): print(w, sol[35*w:35*(w+1)])
